// Helper to determine currency symbol from currency code (as fallback)
const getCurrencySymbol = (currencyCode) => {
  if (currencyCode === "INR") return "₹";
  if (currencyCode === "EUR") return "€";
  if (currencyCode === "GBP") return "£";
  if (currencyCode === "CAD" || currencyCode === "USD" || currencyCode === "AUD") return "$";
  return "$"; // Fallback to dollar sign
};

// Helper to format amount nicely with symbol using Intl.NumberFormat
const formatAmountWithSymbol = (amountVal, currencyCode) => {
  const numericAmount = Math.abs(parseFloat(amountVal));
  try {
    return new Intl.NumberFormat(undefined, {
      style: "currency",
      currency: currencyCode || "USD",
    }).format(numericAmount);
  } catch (e) {
    const symbol = getCurrencySymbol(currencyCode);
    return `${symbol}${numericAmount.toFixed(2)}`;
  }
};

